function sendQuestion(rec){if(!state||state.bank.locked||rec.bankId!==state.bank.id||rec.room!==code){U.toast('الملف مقفل أو تغير؛ افتح السؤال وانسخه للملف الحالي',true);return Promise.resolve(false)}rec.status='pending';rec.error='';persist();return request('question',{bankId:rec.bankId,question:rec.q}).then(function(){rec.status='ok';rec.error='';persist();if(!editor){viewKey='';render()}U.toast('✓ وصل السؤال إلى التلفزيون');return true}).catch(function(e){rec.status='error';rec.error=e.message;persist();if(!editor){viewKey='';render()}toastError(e);return false})}
function legacyQuestions(){showModal('أسئلة النسخة السابقة','<p>تبقى النسخة السابقة محفوظة. اختر سؤالًا لنسخه إلى الملف الحالي ثم أرسله للتلفزيون.</p><div class="stack">'+legacy.map(function(q,i){return btn('legacy-'+i,E(q.t))}).join('')+'</div><div class="actions">'+btn('legacy-close','تم','primary')+'</div>',function(){bind('legacy-close',closeModal);legacy.forEach(function(q,i){bind('legacy-'+i,function(){if(state.bank.locked)return U.toast('افتح ملف الأسئلة أولًا',true);function copy(){closeModal();draft={room:code,bankId:state.bank.id,q:D.copy(q)};draft.q.id=D.uid();editor=true;persist();drawEditor()}if(draft)confirm('استبدال المسودة؟','يُنسخ السؤال القديم إلى مسودة الملف الحالي.','نسخ',copy);else copy()})})})}
function manageBank(){request('export',{}).then(function(result){if(!result||!result.bank)return;if(!result.bank.questions.length){U.toast('لا توجد أسئلة بعد');return}var b=U.importQuestions(result);b.id=state.bank.id;showModal('إدارة جميع الأسئلة','<p>تعديل الأسئلة متاح للمتحكم عندما يكون الملف مفتوحًا.</p><div class="stack">'+b.questions.map(function(q,i){return '<div class="question-row"><h3>'+(i+1)+'. '+E(q.t)+'</h3><small>'+E(q.author)+'</small><div class="actions">'+btn('bank-edit-'+i,'تعديل')+btn('bank-delete-'+i,'حذف','danger')+'</div></div>'}).join('')+'</div><div class="actions">'+btn('bank-manage-close','تم','primary')+'</div>',function(){bind('bank-manage-close',closeModal);b.questions.forEach(function(q,i){bind('bank-edit-'+i,function(){if(state.bank.locked)return U.toast('افتح الملف أولًا',true);function edit(){closeModal();draft={room:code,bankId:b.id,q:D.copy(q)};editor=true;persist();drawEditor()}if(draft)confirm('استبدال المسودة؟','تُستبدل المسودة الحالية بالسؤال المحدد.','تعديل',edit);else edit()});bind('bank-delete-'+i,function(){confirm('حذف السؤال؟',q.t,'حذف',function(){request('question',{bankId:b.id,id:q.id,remove:true}).then(manageBank).catch(toastError)})})})})}).catch(toastError)}
$('#import-file').onchange=function(){var f=this.files[0];if(!f)return;U.readFile(f).then(function(v){var b=U.importQuestions(v);confirm('استيراد ملف الأسئلة؟',b.name+' · '+b.questions.length+' سؤالًا. تُستبدل الأسئلة الحالية، ويبقى اللاعبون المنضمون.','استيراد',function(){request('import',{file:{kind:'dabt-questions',bank:b}}).then(function(){U.toast('تم استيراد الأسئلة')}).catch(toastError)})}).catch(toastError)};
function updateClock(){var s=state&&state.session,e=$('#clock');if(s&&e){var left=s.paused?s.left:Math.max(0,s.left-(Date.now()-musicStamp));var value=String(s.phase==='reveal'?'النتيجة':Math.ceil(left/1000));if(e.textContent!==value)e.textContent=value}}
